-- Schéma SQLite : comptes, classes, matières, élèves, notes, absences.
CREATE TABLE users (id INTEGER PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('admin','student')));
CREATE TABLE classes (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE subjects (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, coefficient REAL NOT NULL DEFAULT 1);
CREATE TABLE students (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, first_name TEXT NOT NULL, last_name TEXT NOT NULL, class_id INTEGER REFERENCES classes(id) ON DELETE SET NULL);
CREATE TABLE grades (id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE, subject_id INTEGER NOT NULL REFERENCES subjects(id) ON DELETE CASCADE, value REAL NOT NULL CHECK (value BETWEEN 0 AND 20), coefficient REAL NOT NULL DEFAULT 1, graded_on TEXT NOT NULL);
CREATE TABLE absences (id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE, absent_on TEXT NOT NULL, justified INTEGER NOT NULL DEFAULT 0, reason TEXT);
